	CONSTRAINT "activity_cost_level_range" CHECK ("memento_activity"."costLevel" is null or ("memento_activity"."costLevel" >= 0 and "memento_activity"."costLevel" <= 3)),
	CONSTRAINT "activity_time_range_order" CHECK ("memento_activity"."startTime" is null or "memento_activity"."endTime" is null or "memento_activity"."startTime" <= "memento_activity"."endTime"),
	CONSTRAINT "activity_source_type_owner_guard" CHECK (("memento_activity"."sourceType" = 'curated' and "memento_activity"."createdByUserId" is null) or ("memento_activity"."sourceType" = 'user' and "memento_activity"."createdByUserId" is not null))
);
